    public virtual string? parseOrderState(string? state)
    {
        Dictionary<string, object> states = new Dictionary<string, object>() {
            { "OPEN", "open" },
            { "REJECTED", "rejected" },
            { "FILLED", "closed" },
            { "CANCELED", "canceled" },
            { "PART_FILLED", "open" },
            { "EXPIRED", "expired" },
        };
        return this.safeString(states, state, state);
    }

