    public override Dictionary<string, object> parseTrade(object trade, object market = null)
    {
        //
        //     {
        //         "exOrdId":281685751028507,
        //         "tradeId":281685434947633,
        //         "execId":8847494003,
        //         "side":"BUY",
        //         "symbol":"AAVE-USDT",
        //         "price":405.34,
        //         "qty":0.1,
        //         "fee":0.162136,
        //         "timestamp":1634559249687
        //     }
        //
        string? orderId = this.safeString(trade, "exOrdId");
        string? tradeId = this.safeString(trade, "tradeId");
        string? side = this.safeStringLower(trade, "side");
        string? marketId = this.safeString(trade, "symbol");
        string? priceString = this.safeString(trade, "price");
        string? amountString = this.safeString(trade, "qty");
        Int64? timestamp = this.safeInteger(trade, "timestamp");
        string? datetime = this.iso8601(timestamp);
        Dictionary<string, object> marketResolved = this.safeMarket(marketId, market, "-");
        string? symbol = ((string)(marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("symbol") ? ((IDictionary<string, object>)marketResolved)["symbol"] : null));
        Dictionary<string, object> fee = null;
        string? feeCostString = this.safeString(trade, "fee");
        if ((feeCostString != null))
        {
            string? feeCurrency = ((string)(marketResolved != null && ((IDictionary<string, object>)marketResolved).ContainsKey("quote") ? ((IDictionary<string, object>)marketResolved)["quote"] : null));
            fee = new Dictionary<string, object>() {
                { "cost", feeCostString },
                { "currency", feeCurrency },
            };
        }
        return this.safeTrade(new Dictionary<string, object>() {
            { "id", tradeId },
            { "timestamp", timestamp },
            { "datetime", datetime },
            { "symbol", symbol },
            { "order", orderId },
            { "type", null },
            { "side", side },
            { "takerOrMaker", null },
            { "price", priceString },
            { "amount", amountString },
            { "cost", null },
            { "fee", fee },
            { "info", trade },
        }, marketResolved);
    }

